def test_ci01_compositional_quarantine():
    def quarantined(failures, threshold):
        return failures >= threshold
    assert quarantined(3, 3) is True
    assert quarantined(2, 3) is False

def test_ci01_negative_stable_never_quarantined():
    def quarantined(failures, threshold):
        return failures >= threshold
    assert quarantined(0, 1) is False

def test_ci01_boundary_exact_threshold():
    def quarantined(failures, threshold):
        return failures >= threshold
    assert quarantined(1, 1) is True

def test_ci02_compositional_shed_order():
    def admit(queue, cap, job):
        if len(queue) >= cap:
            return queue, False
        return queue + [job], True
    q, ok = admit(['a'], 2, 'b')
    assert (q, ok) == (['a', 'b'], True)
    q, ok = admit(q, 2, 'c')
    assert (q, ok) == (['a', 'b'], False)

def test_ci02_negative_overflow_rejected():
    def admit(queue, cap, job):
        if len(queue) >= cap:
            return queue, False
        return queue + [job], True
    assert admit(['a', 'b'], 2, 'c') == (['a', 'b'], False)

def test_ci02_boundary_zero_capacity():
    def admit(queue, cap, job):
        if len(queue) >= cap:
            return queue, False
        return queue + [job], True
    assert admit([], 0, 'a') == ([], False)
